contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address ref, uint256 waitSeconds) public {
        require(ref != address(0));
        require(ref != address(this));
        require(waitSeconds >= 1 && waitSeconds <= 86400);

        c.seedMarket(0);
        c.getFreeKilo();

        // ensure positive pending drugs before collecting
        require(c.getMyDrugs() > 0);

        // if enough time hasn't passed, call again to update lastCollect; we only need pending > 0
        if (c.getDrugsSinceLastCollect(address(this)) == 0) {
            c.collectDrugs(ref);
        }

        uint256 pending = c.getMyDrugs();
        require(pending > 0);
        uint256 refKilosBefore = c.Kilos(ref);

        c.collectDrugs(ref);

        uint256 refKilosAfter = c.Kilos(ref);

        assert(refKilosAfter == refKilosBefore + pending / 86400);
    }

    receive() external payable {}
}

